<!doctype html><html lang="da"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Betaling · Nodexa</title><style>body{margin:0;background:#07111c;color:#edf6ff;font:14px Inter,system-ui}.wrap{max-width:760px;margin:50px auto;padding:18px}.card{background:#0b1825;border:1px solid #1b3449;border-radius:12px;padding:24px}.muted{color:#7e96aa}.total{font-size:30px;font-weight:900;margin:18px 0}.pay{background:#0f2132;border:1px solid #29445d;border-radius:9px;padding:15px;margin:9px 0}.selected{border-color:#3b8cff}.badge{float:right;font-size:10px;padding:4px 8px;border-radius:12px;background:#172a3b}.warn{background:#302315;border:1px solid #67491e;color:#ffd08a;padding:13px;border-radius:8px;margin-top:18px}.back{color:#9ab0c2;text-decoration:none}</style></head><body><div class="wrap"><a class="back" href="/client">← Client Area</a><div class="card" style="margin-top:16px"><h1>Betaling</h1><div class="muted">Faktura {{$invoice->number}}</div><div class="total">{{number_format((float)$invoice->total,2,',','.')}} {{$invoice->currency}}</div><h3>Valgt betalingsmetode</h3>@php($selected=$order?$gateways->firstWhere('gateway',$order->payment_method):null)@if($selected)<div class="pay selected"><span class="badge">{{$selected->test_mode?'TEST':'AKTIV'}}</span><strong>{{$selected->name}}</strong><div class="muted" style="margin-top:5px">{{$selected->gateway}}</div></div>@else<div class="warn">Den valgte betalingsmetode er ikke længere aktiv.</div>@endif<div class="warn"><strong>Checkout er klar til gateway-forbindelsen.</strong><br>Ordren bliver ikke længere sendt direkte tilbage til Client Area. Næste trin er at forbinde denne side til den valgte gateways betalingssession og webhook, så fakturaen først markeres betalt efter bekræftet betaling.</div></div></div></body></html>